"""Synthetic transaction fixtures for the preprocessing tests.

=============================================================================
SYNTHETIC TEST DATA - NOT IBM AML DATA
=============================================================================
The rows produced here are generated by a small deterministic function in this
file. They are **not** IBM AML data, not a sample of it, and not derived from it.
No count, timestamp, amount, account or class ratio produced by this module says
anything about the real dataset, and nothing here is ever written to
``data/raw/`` or named ``HI-Small_Trans.csv``. Files go into pytest's
``tmp_path`` and vanish with the test.

The *column names* are the real verified ones, and that is deliberate: these
fixtures exercise ``AmlPreprocessor``, which is written against those exact
columns. Testing it with invented headers would test nothing. The header written
by :func:`write_transactions_csv` also repeats ``Account`` exactly as the real
file's header does, so the duplicate-header handling every consumer depends on
is exercised rather than assumed.

The generator deliberately emits rows **out of timestamp order**, because the
real file is out of timestamp order too. A fixture that arrived pre-sorted would
let a broken chronological split pass.
"""

from __future__ import annotations

import csv
from collections.abc import Iterable, Sequence
from datetime import datetime, timedelta
from pathlib import Path
from typing import Any

from pandas import DataFrame

from infrastructure.data.schemas.ibm_aml_schema import (
    COL_AMOUNT_PAID,
    COL_AMOUNT_RECEIVED,
    COL_FROM_ACCOUNT,
    COL_FROM_BANK,
    COL_IS_LAUNDERING,
    COL_PAYMENT_CURRENCY,
    COL_PAYMENT_FORMAT,
    COL_RECEIVING_CURRENCY,
    COL_TIMESTAMP,
    COL_TO_ACCOUNT,
    COL_TO_BANK,
    RAW_COLUMN_ORDER,
    TIMESTAMP_FORMAT,
)

TEST_DATA_NOTICE = "SYNTHETIC TEST DATA - NOT IBM AML DATA"

RAW_HEADER_FIELDS: tuple[str, ...] = (
    "Timestamp",
    "From Bank",
    "Account",
    "To Bank",
    "Account",
    "Amount Received",
    "Receiving Currency",
    "Amount Paid",
    "Payment Currency",
    "Payment Format",
    "Is Laundering",
)
"""The header line as the real file writes it: ``Account`` twice.

Kept verbatim because that repetition is the one structural quirk of the input
that every downstream name depends on. pandas renames the second occurrence to
``Account.1``; a fixture that wrote unique headers would hide a bug there.
"""

FIXTURE_CURRENCIES: tuple[str, ...] = ("US Dollar", "Euro", "Yen")
FIXTURE_FORMATS: tuple[str, ...] = ("ACH", "Cheque", "Wire")

START = datetime(2020, 1, 1, 0, 0)
"""Fixture epoch. 2020, not 2022, so no timestamp here can be mistaken for a
real one."""


def make_transactions(
    *,
    rows: int = 60,
    days: int = 6,
    accounts: int = 8,
    positive_every: int = 7,
    shuffled: bool = True,
) -> list[dict[str, Any]]:
    """Generate deterministic synthetic transactions.

    Args:
        rows: How many rows to produce.
        days: How many calendar days to spread them over.
        accounts: Size of the account pool, so histories actually accumulate.
        positive_every: Every n-th row carries label 1. Set to 0 for none.
        shuffled: Emit out of timestamp order, as the real file is.

    Returns:
        Rows as dictionaries keyed by the verified parsed-frame column names.
    """
    generated: list[dict[str, Any]] = []
    for index in range(rows):
        # Spread across days, then across minutes within a day, with repeats so
        # that timestamp ties occur and the tie policy is exercised.
        day = index % days
        minute = (index // days) * 3 % 600
        moment = START + timedelta(days=day, minutes=minute)
        sender = index % accounts
        receiver = (index * 3 + 1) % accounts
        amount = 100.0 + (index % 17) * 250.5

        generated.append(
            {
                COL_TIMESTAMP: moment.strftime(TIMESTAMP_FORMAT),
                COL_FROM_BANK: f"{10 + sender:03d}",
                COL_FROM_ACCOUNT: f"TEST{sender:05d}",
                COL_TO_BANK: f"{10 + receiver:03d}",
                COL_TO_ACCOUNT: f"TEST{receiver:05d}",
                COL_AMOUNT_RECEIVED: amount,
                COL_RECEIVING_CURRENCY: FIXTURE_CURRENCIES[index % 3],
                COL_AMOUNT_PAID: amount,
                COL_PAYMENT_CURRENCY: FIXTURE_CURRENCIES[index % 3],
                COL_PAYMENT_FORMAT: FIXTURE_FORMATS[index % 3],
                COL_IS_LAUNDERING: (
                    1 if positive_every and index % positive_every == 0 else 0
                ),
            }
        )

    if not shuffled:
        generated.sort(key=lambda row: str(row[COL_TIMESTAMP]))
    return generated


def make_frame(**kwargs: Any) -> DataFrame:
    """Generated rows as a frame carrying the verified column names."""
    return DataFrame(make_transactions(**kwargs), columns=list(RAW_COLUMN_ORDER))


def write_transactions_csv(
    path: Path,
    records: Iterable[dict[str, Any]] | None = None,
    *,
    header: Sequence[str] = RAW_HEADER_FIELDS,
    **kwargs: Any,
) -> Path:
    """Write synthetic rows to ``path`` using the real file's header shape.

    Args:
        path: Destination inside ``tmp_path``. Parents are created.
        records: Rows to write. Generated from ``kwargs`` when omitted.
        header: Header fields, duplicated ``Account`` included by default.
        **kwargs: Forwarded to :func:`make_transactions` when ``records`` is
            None.

    Returns:
        The written path.
    """
    written = list(records) if records is not None else make_transactions(**kwargs)
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.writer(handle, lineterminator="\n")
        writer.writerow(header)
        writer.writerows(
            [record.get(column, "") for column in RAW_COLUMN_ORDER]
            for record in written
        )
    return path
